/* @lc app=leetcode id=3366 lang=kotlin */ class Solution { fun minArraySum(nums: IntArray, k: Int, op1: Int, op2: Int): Int = nums.fold(Array(op1 + 1) { a -> IntArray(op2 + 1) { b -> if (a == 0 && b == 0) 0 else 1_000_000_000 } }) { dp, x -> Array(op1 + 1) { a -> IntArray(op2 + 1) { b -> listOfNotNull(dp[a][b] + x, if (a > 0) dp[a - 1][b] + (x + 1) / 2 else null, if (b > 0 && x >= k) dp[a][b - 1] + x - k else null, if (a > 0 && b > 0) listOfNotNull(if ((x + 1) / 2 >= k) (x + 1) / 2 - k else null, if (x >= k) (x - k + 1) / 2 else null).minOrNull()?.let { dp[a - 1][b - 1] + it } else null).min() } } }.flatMap { it.toList() }.min() }